INSERT INTO rent_transaction (
    region_code, housing_type, dong_name, jibun, complex_name,
    area, deal_type, deposit, monthly_rent, floor, build_year,
    deal_ym, deal_day, contract_type, contract_term, json
) VALUES

(
    #{r.regionCode}, #{r.housingType}, #{r.dongName}, #{r.jibun}, #{r.complexName},
    #{r.area}, #{r.dealType}, #{r.deposit}, #{r.monthlyRent}, #{r.floor}, #{r.buildYear},
    #{r.dealYm}, #{r.dealDay}, #{r.contractType}, #{r.contractTerm}, #{r.json}
)

mapper.delete:
DELETE FROM rent_transaction
 WHERE region_code = #{regionCode}
   AND deal_ym = #{dealYm}
   AND housing_type = #{housingType}

mapper.select:
SELECT deal_ym, deposit, area
  FROM rent_transaction
 WHERE region_code  = #{regionCode}
   AND housing_type = #{housingType}
   AND deal_type = #{dealType}
   AND deal_ym BETWEEN #{startYm} AND #{endYm}
   AND area BETWEEN #{areaMinSqm} AND #{areaMaxSqm}
   AND deposit > 0
 ORDER BY deal_ym

SELECT
    MAX(CASE WHEN dep_rn  = CEIL(0.25 * total) THEN deposit      END) AS deposit_q1,
    MAX(CASE WHEN dep_rn  = CEIL(0.50 * total) THEN deposit      END) AS deposit_q2,
    MAX(CASE WHEN dep_rn  = CEIL(0.75 * total) THEN deposit      END) AS deposit_q3,
    MAX(CASE WHEN rent_rn = CEIL(0.25 * total) THEN monthly_rent END) AS rent_q1,
    MAX(CASE WHEN rent_rn = CEIL(0.50 * total) THEN monthly_rent END) AS rent_q2,
    MAX(CASE WHEN rent_rn = CEIL(0.75 * total) THEN monthly_rent END) AS rent_q3,
    MAX(total) AS sample_count
FROM (
    SELECT deposit, monthly_rent,
           ROW_NUMBER() OVER (ORDER BY deposit)      AS dep_rn,
           ROW_NUMBER() OVER (ORDER BY monthly_rent) AS rent_rn,
           COUNT(*)     OVER ()                      AS total
      FROM rent_transaction


     WHERE region_code LIKE CONCAT(#{request.regionCode}, '%')


     WHERE region_code = #{request.regionCode}


       AND housing_type = #{request.housingType}
       AND deal_type    = #{request.dealType}
       AND deal_ym      BETWEEN #{startYm} AND #{endYm}
       AND area         BETWEEN #{areaMinSqm} AND #{areaMaxSqm}
       AND deposit      BETWEEN #{request.depositMin} AND #{request.depositMax}
       AND deposit > 0

       AND monthly_rent >= #{request.monthlyRentMin}


       AND monthly_rent <= #{request.monthlyRentMax}

) t

SELECT region_code,
       MAX(CASE WHEN dep_rn  = CEIL(0.50 * total) THEN deposit      END) AS deposit_median,
       MAX(CASE WHEN rent_rn = CEIL(0.50 * total) THEN monthly_rent END) AS rent_median,
       MAX(total) AS sample_count
  FROM (
       SELECT region_code, deposit, monthly_rent,
              ROW_NUMBER() OVER (PARTITION BY region_code ORDER BY deposit)      AS dep_rn,
              ROW_NUMBER() OVER (PARTITION BY region_code ORDER BY monthly_rent) AS rent_rn,
              COUNT(*)     OVER (PARTITION BY region_code)                       AS total
         FROM rent_transaction
        WHERE region_code IN

                  #{code}

          AND housing_type = #{housingType}
          AND deal_type    = #{dealType}
          AND deal_ym      BETWEEN #{startYm} AND #{endYm}
          AND area         BETWEEN #{areaMinSqm} AND #{areaMaxSqm}
          AND deposit      BETWEEN #{depositMin} AND #{depositMax}
          AND deposit > 0

          AND monthly_rent >= #{monthlyRentMin}


          AND monthly_rent <= #{monthlyRentMax}

  ) t
 GROUP BY region_code
